import{_ as p,a0 as s,w as r,s as u,I as l,x as e,a1 as o,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"GNOME “文件”引入最受歡迎的功能：“新建文件”菜單 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME “文件”引入最受歡迎的功能：“新建文件”菜單 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME “文件”引入最受歡迎的功能：“新建文件”菜單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME “文件”引入最受歡迎的功能：“新建文件”菜單 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220919 GNOME Files Introduces Most-Requested Feature- New File Menu","title":"GNOME “文件”引入最受歡迎的功能：“新建文件”菜單","tag":"202209","desc":""},"relativePath":"202209/20220919 GNOME Files Introduces Most-Requested Feature- New File Menu.md","filePath":"[post].md"}'),a={name:"202209/20220919 GNOME Files Introduces Most-Requested Feature- New File Menu.md"};function m(w,t,N,f,g,M){const n=s("Link");return r(),u("div",null,[t[23]||(t[23]=l("h1",{id:"gnome-文件-引入最受歡迎的功能-新建文件-菜單",tabindex:"-1"},[e("GNOME “文件”引入最受歡迎的功能：“新建文件”菜單 "),l("a",{class:"header-anchor",href:"#gnome-文件-引入最受歡迎的功能-新建文件-菜單","aria-label":"Permalink to “GNOME “文件”引入最受歡迎的功能：“新建文件”菜單”"},"​")],-1)),t[24]||(t[24]=l("blockquote",null,[l("p",null,"這是 GNOME “文件”中的“新建文件”功能，它為你提供了一種創建文檔和文件的新方法。讓我們看一看。")],-1)),t[25]||(t[25]=l("p",null,[e("無需在後端進行更多調整。通過“"),l("ruby",null,[e("文件"),l("rt",null,"Files")]),e("”（又名 Nautilus）中的上下文菜單創建新文檔/新文件的最令人期待的功能終於到來了。")],-1)),l("p",null,[t[1]||(t[1]=e("作為 ",-1)),o(n,{href:"https://debugpointnews.com/gsoc-2022/"},{default:i(()=>[...t[0]||(t[0]=[e("谷歌編程之夏 2022",-1)])]),_:1}),t[2]||(t[2]=e(" 的一部分，（由 Ignacy Kuchciński 開發的）這個新功能最近經過審查併合併到 “文件” 的主分支中。",-1))]),t[26]||(t[26]=d('<h3 id="它看起來如何" tabindex="-1">它看起來如何 <a class="header-anchor" href="#它看起來如何" aria-label="Permalink to “它看起來如何”">​</a></h3><p>當你右鍵單擊文件時，上下文菜單有一個新選項“<ruby>新建文件<rt>New File</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/09/New-File-Option-in-Files-Context-Menu.jpg" alt="New File Option in Files Context Menu"></p><p>GNOME “文件”中的“<ruby>新建文件<rt>New File</rt></ruby>”選項啓動一個操作窗口，如下圖所示。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/09/GNOME-Files-New-Document-Action-Dialog.jpg" alt="GNOME Files New File Action Dialog"></p><p>當它啓動上述對話框時，會在後台發生一些事情。</p><p>你可能知道你可以在主目錄中創建一個帶有模板的 <code>Template</code> 文件夾，以便輕鬆訪問常用的文檔類型。因此，GNOME “文件” 會檢查你是否有該目錄。</p><p>如果當前存在一個帶有模板的 <code>Template</code> 目錄，你能通過那些文檔類型的列表以創建新文檔。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/09/GNOME-Files-New-Document-Template-Dialog.jpg" alt="GNOME Files New File Template Dialog (when some templates present)"></p><p>如果你沒有任何模板（很可能），GNOME “文件”會掃描你的系統並根據系統中已安裝的應用程序顯示常見文件類型的列表。</p><p>例如，文本編輯器、LibreOffice 文檔類型（電子表格、演示文稿）等。</p><p>這裏還發生了一些其他事情。當你為新文檔選擇文件類型時，系統會選擇默認的文件擴展名。這是文件名文本框中的受保護標籤。</p><p>此外，如果你沒有安裝任何模板或任何應用程序，則根本不會顯示“新建文件”菜單選項。</p><h3 id="未來路線圖" tabindex="-1">未來路線圖 <a class="header-anchor" href="#未來路線圖" aria-label="Permalink to “未來路線圖”">​</a></h3><p>開發人員還提出了未來對該功能的增強，更大程度地擴展其功能。</p><p>當沒有可用的模板時，對話框將如下所示。它將允許你通過選擇應用程序來創建文件，包括空白文件。</p><p>此外，你可以直接啓動軟件來安裝一些可以幫助你創建相應文件類型的應用程序。</p><p>由於這個功能比較複雜，可能會在以後開發。目前還沒有時間表。</p><h3 id="這在-文件-v43-中可用-通過-gnome-43-嗎" tabindex="-1">這在“文件” v43 中可用（通過 GNOME 43）嗎？ <a class="header-anchor" href="#這在-文件-v43-中可用-通過-gnome-43-嗎" aria-label="Permalink to “這在“文件” v43 中可用（通過 GNOME 43）嗎？”">​</a></h3><p>但是，在我看來，這種變化需要一些額外的設計審查。我覺得它不完整。例如，當你有模板時，你無法創建標準文檔類型（文本、LibreOffice 文檔）—— 這兩個對話框是互斥的。另外，我發現了一些小 BUG。</p>',20)),l("p",null,[t[5]||(t[5]=e("儘管該功能目前 ",-1)),o(n,{href:"https://gitlab.gnome.org/GNOME/nautilus/-/merge_requests/914"},{default:i(()=>[...t[3]||(t[3]=[e("已獲得批准和合並",-1)])]),_:1}),t[6]||(t[6]=e("，但由於日程衝突，它無法進入 ",-1)),o(n,{href:"https://www.debugpoint.com/gnome-43/"},{default:i(()=>[...t[4]||(t[4]=[e("GNOME 43候選版本",-1)])]),_:1}),t[7]||(t[7]=e("。",-1))]),t[27]||(t[27]=l("p",null,"希望在經過一輪良好的審查和測試後，你可以在明年的 GNOME 44 版本中獲得此功能。",-1)),t[28]||(t[28]=l("h3",{id:"總結",tabindex:"-1"},[e("總結 "),l("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[29]||(t[29]=l("p",null,"總的來説，這是一個優雅的功能，我認為如今沒有任何其他文件管理器具有這種先進的設計。一旦這個“文件”的“新建文件”功能被完全實現，它將會是其出色功能集的一個很好的補充。",-1)),t[30]||(t[30]=l("p",null,"那麼，你喜歡這個新設計嗎？請在評論框中告訴我。",-1)),t[31]||(t[31]=l("hr",null,null,-1)),l("p",null,[t[9]||(t[9]=e("via: ",-1)),o(n,{href:"https://www.debugpoint.com/gnome-files-new-file-document/"},{default:i(()=>[...t[8]||(t[8]=[e("https://www.debugpoint.com/gnome-files-new-file-document/",-1)])]),_:1})]),l("p",null,[t[14]||(t[14]=e("作者：",-1)),o(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...t[10]||(t[10]=[e("Arindam",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),o(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[11]||(t[11]=[e("lkxed",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),o(n,{href:"https://github.com/littlebirdnest"},{default:i(()=>[...t[12]||(t[12]=[e("littlebirdnest",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[20]||(t[20]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const E=p(a,[["render",m]]);export{T as __pageData,E as default};
